+        this.edgePage = new EdgePage(driver, actions);
+    }
+
+    // ==================== AUTHENTICATION ====================
+
+    @Given("I navigate to the login page")
+    public void iNavigateToLoginPage() {
+        loginPage.navigateToLogin();
+    }
+
+    @Then("the login heading should contain {string}")
